const input = $input.all();

let webhookJson = {};
let createJson = {};

try { webhookJson = $('Webhook Ticket').first().json || {}; } catch (e) { webhookJson = {}; }
try { createJson = $('Create Ticket').first().json || {}; } catch (e) { createJson = {}; }

const body = (webhookJson.body && typeof webhookJson.body === 'object') ? webhookJson.body : {};

const extractError = (raw) => {
  if (raw == null) return null;
  if (typeof raw === 'string') return raw;
  if (typeof raw === 'object') {
    if (raw.message) return String(raw.message);
    if (raw.code) return String(raw.code);
    if (typeof raw.error !== 'undefined') return extractError(raw.error);
    try {
      const s = JSON.stringify(raw);
      return s && s !== '{}' ? s : null;
    } catch (e) {
      return null;
    }
  }
  return String(raw);
};

let ticketId = null;
let errorMessage = null;

if (typeof createJson.id === 'number') {
  ticketId = createJson.id;
} else {
  let err = extractError(createJson.error);
  if (!err) {
    for (const nodeName of ['Init Session', 'Kill Session']) {
      let n = {};
      try { n = $('' + nodeName).first().json || {}; } catch (e) { n = {}; }
      err = extractError(n.error);
      if (err) break;
    }
  }
  errorMessage = err || 'Fallo en la creacion del ticket GLPI';
}

return [{
  json: {
    ok: ticketId !== null,
    ticket_id: ticketId,
    errorMessage: errorMessage,
    event_id: body.event_id || null,
    name: body.name,
    content: body.content,
    urgency: body.urgency
  }
}];
